import re
from datetime import datetime

INTESTAZIONE = re.compile(r"^#\s*(\w+)\s*:\s*(.+?)\s*$")


def _num(s):
    return float(s.strip().replace(",", "."))


def leggi_file(testo):
    meta, forze = {}, []
    for riga in testo.splitlines():
        if m := INTESTAZIONE.match(riga):
            meta[m[1].lower()] = m[2]
        elif riga.strip() and not riga.startswith("t;"):
            forze.append(_num(riga.split(";")[1]))
    for chiave in ("provino", "materiale", "data", "a0"):
        if chiave not in meta:
            raise ValueError(f"intestazione incompleta: manca {chiave}")
    if not forze:
        raise ValueError("nessuna misura")
    return {
        "provino": meta["provino"],
        "materiale": meta["materiale"],
        "data": datetime.strptime(meta["data"], "%d/%m/%Y").date(),
        "A0": _num(meta["a0"]),
        "Fmax": max(forze),
    }

import sqlite3
from pathlib import Path


def crea_db(con):
    con.execute(
        "CREATE TABLE IF NOT EXISTS prove (provino TEXT PRIMARY KEY, materiale TEXT NOT NULL, "
        "data TEXT NOT NULL, A0 REAL NOT NULL, Fmax REAL NOT NULL, Rm REAL NOT NULL)"
    )


def importa_cartella(con, cartella):
    crea_db(con)
    nuovi, saltati, errori = 0, 0, []
    with con:
        for f in sorted(Path(cartella).glob("*.txt")):
            try:
                p = leggi_file(f.read_text(encoding="utf-8"))
            except ValueError as e:
                errori.append(f"{f.name}: {e}")
                continue
            cur = con.execute(
                "INSERT OR IGNORE INTO prove VALUES (?, ?, ?, ?, ?, ?)",
                (p["provino"], p["materiale"], p["data"].isoformat(), p["A0"], p["Fmax"], round(p["Fmax"] / p["A0"], 1)),
            )
            if cur.rowcount:
                nuovi += 1
            else:
                saltati += 1
    return nuovi, saltati, errori

import statistics


def statistiche(con, dal=None):
    sql = "SELECT materiale, Rm FROM prove"
    parametri = []
    if dal is not None:
        sql += " WHERE data >= ?"
        parametri.append(dal.isoformat())
    gruppi = {}
    for materiale, Rm in con.execute(sql + " ORDER BY materiale, provino", parametri):
        gruppi.setdefault(materiale, []).append(Rm)
    righe = []
    for materiale, valori in gruppi.items():
        righe.append({
            "materiale": materiale,
            "n": len(valori),
            "Rm_medio": round(statistics.mean(valori), 1),
            "Rm_min": min(valori),
            "s": round(statistics.stdev(valori), 1) if len(valori) > 1 else None,
        })
    return righe

from docx import Document


def _fmt(x):
    return "–" if x is None else f"{x:.1f}".replace(".", ",")


def scrivi_report(file, righe, titolo, generato_il):
    doc = Document()
    doc.add_heading(titolo, level=1)
    doc.add_paragraph(f"Generato il {generato_il:%d/%m/%Y} · {sum(r['n'] for r in righe)} prove")
    t = doc.add_table(rows=1, cols=5)
    for c, testo in zip(t.rows[0].cells, ["Materiale", "n", "Rm medio [MPa]", "Rm min [MPa]", "s [MPa]"]):
        c.text = testo
        c.paragraphs[0].runs[0].bold = True
    for r in righe:
        celle = t.add_row().cells
        valori = [r["materiale"], str(r["n"]), _fmt(r["Rm_medio"]), _fmt(r["Rm_min"]), _fmt(r["s"])]
        for c, v in zip(celle, valori):
            c.text = v
    doc.save(file)
    return doc
